# Let me fix the symbolic input creation
import angr
import claripy

proj = angr.Project("{TARGET}", auto_load_libs=False)

# Create symbolic input - 64 characters
flag_len = 64
flag = claripy.BVS('flag', flag_len * 8)

# Create the initial state at entry
state = proj.factory.entry_state(
    args=["./target"],
    stdin=angr.SimFile('/dev/stdin', content=flag + claripy.BVV(b'\n')),
)

# Constrain to printable ASCII
for i in range(flag_len):
    byte = flag.get_byte(i)
    state.solver.add(byte >= 0x20)
    state.solver.add(byte <= 0x7e)

# Create simulation manager
simgr = proj.factory.simulation_manager(state)

def is_successful(state):
    """Check if state printed 'Correct!'"""
    try:
        stdout = state.posix.dumps(1)
        if b'Correct' in stdout:
            return True
    except:
        pass
    return False

def is_failed(state):
    """Check if state printed 'Wrong!'"""
    try:
        stdout = state.posix.dumps(1)
        if b'Wrong' in stdout:
            return True
    except:
        pass
    return False

# First let's just step through a few instructions to see what happens
print("Stepping through initial execution...")
for i in range(10):
    simgr.step()
    print(f"Step {i}: {len(simgr.active)} active states")
    if simgr.active:
        state = simgr.active[0]
        print(f"  IP: {hex(state.solver.eval(state.regs.rip))}")

# Let's try exploration with a step limit
print("\nStarting bounded exploration...")
try:
    for i in range(50):
        simgr.step()
        # Check for success
        for s in simgr.active:
            try:
                out = s.posix.dumps(1)
                if b'Correct' in out:
                    print(f"Found Correct! at step {i}")
                    solution = s.solver.eval(flag, cast_to=bytes)
                    print(f"Solution: {solution}")
                    break
                elif b'Wrong' in out:
                    simgr.active.remove(s)
                    simgr.deadended.append(s)
            except:
                pass
        if not simgr.active:
            break
        print(f"Step {i}: {len(simgr.active)} active")
except Exception as e:
    print(f"Error: {e}")

print(f"\nFinal state: {len(simgr.active)} active, {len(simgr.deadended)} dead")
